import { useState } from "react";
import { Zap, ChevronDown } from "lucide-react";
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator } from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { ThemeToggle } from "@/components/ThemeToggle";
import { CommandMenu } from "@/components/dashboard/CommandMenu";
import { DynamicSidebar } from "@/components/dashboard/DynamicSidebar";
import { useLayout } from "@/lib/layout/LayoutContext";
import { navigationRegistry } from "@/lib/navigation";
import { WIDGET_REGISTRY } from "@/lib/widgetRegistry";

export function MissionControlLayout() {
  const [activeTab, setActiveTab] = useState<string>("dashboard");
  const { currentLayout, setLayoutMode, layouts } = useLayout();
  
  // Mock signals for debug
  const isConnected = true;
  const healthStatus = { status: 'HEALTHY' };

  const activeItem = navigationRegistry.getItem(activeTab);

  return (
    <div className="min-h-screen max-h-screen flex flex-col overflow-hidden bg-[#020205] bg-grid-pattern">
      <CommandMenu setActiveTab={setActiveTab} activeTab={activeTab} />

      <header className="h-16 shrink-0 border-b border-white/5 bg-black/40 backdrop-blur-xl flex items-center justify-between px-6 z-30">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded bg-primary/20 flex items-center justify-center border border-primary/30">
              <Zap size={18} className="text-primary animate-pulse" />
            </div>
            <div className="flex flex-col">
              <span className="text-sm font-bold tracking-tighter text-white uppercase italic">Brunella Cortex</span>
              <span className="text-[10px] font-mono text-primary/60 tracking-widest leading-none">NEURAL NETWORK OS v2.3.0</span>
            </div>
          </div>
          
          <div className="h-4 w-[1px] bg-white/10 mx-2" />
          
          <nav className="flex items-center gap-1">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="sm" className="text-xs font-mono text-zinc-500 hover:text-zinc-300 transition-colors px-2 py-1 rounded gap-1">
                  LAYOUT: <span className="font-bold text-white">{currentLayout.name.toUpperCase().replace(' ', '_')}</span> <ChevronDown size={14} />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent className="w-56" align="start">
                <DropdownMenuLabel>Válasszon Elrendezést</DropdownMenuLabel>
                <DropdownMenuSeparator />
                {layouts.modes.map((mode) => (
                  <DropdownMenuItem key={mode.id} onClick={() => setLayoutMode(mode.id)} className="cursor-pointer">
                    <span className="font-bold">{mode.name}</span>
                    <span className="ml-auto text-xs text-zinc-500">{mode.id}</span>
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          </nav>
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-3 bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
             <div className={cn(
               "w-2 h-2 rounded-full",
               isConnected && healthStatus?.status === 'HEALTHY' ? "bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]" : "bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.8)]"
             )} />
             <span className="text-[10px] font-mono font-bold text-zinc-400">{isConnected ? healthStatus?.status === 'HEALTHY' ? "CORE_ONLINE" : "CORE_DEGRADED" : "CORE_OFFLINE"}</span>
          </div>
          <ThemeToggle />
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <DynamicSidebar activeTab={activeTab} onTabChange={setActiveTab} />
        
        <main className="flex-1 p-6 overflow-hidden relative">
          {activeTab === 'dashboard' ? (
            /* Smart Grid for Mission Control */
            <div 
              className="h-full w-full grid"
              style={{
                gridTemplateAreas: currentLayout.gridTemplateAreas.map(area => `'${area}'`).join(' '),
                gridTemplateColumns: currentLayout.gridTemplateColumns,
                gridTemplateRows: currentLayout.gridTemplateRows,
                gap: '1rem'
              }}
            >
              {Object.entries(currentLayout.widgetAssignments).map(([widgetId, gridArea]) => {
                const widget = WIDGET_REGISTRY[widgetId];
                if (!widget) return null;
                const Component = widget.component;
                return (
                  <div key={widgetId} style={{ gridArea }} className="relative overflow-hidden rounded-2xl border border-white/5 bg-black/20 backdrop-blur-md">
                    <div className="h-full w-full overflow-hidden">
                      <Component />
                    </div>
                  </div>
                );
              })}
            </div>
          ) : (
            /* Regular Tabs */
            <div className="h-full w-full overflow-auto custom-scrollbar">
              {activeItem?.component || <div className="text-zinc-500 font-mono">CONTENT_MISSING: {activeTab}</div>}
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

import { createContext, useContext, useState, ReactNode, useCallback, useMemo } from 'react';
import { LayoutModeId, LayoutMode, DashboardLayoutConfig } from './types';

// Define default layout configurations
const defaultLayoutConfig: DashboardLayoutConfig = {
  defaultMode: 'default-dashboard',
  modes: [
    {
      id: 'default-dashboard',
      name: 'Default Dashboard',
      description: 'A standard multi-widget dashboard view.',
      gridTemplateAreas: [
        '"sidebar main-top main-top"',
        '"sidebar main-left main-right"',
        '"sidebar footer footer"'
      ],
      gridTemplateColumns: 'auto 1fr 1fr',
      gridTemplateRows: '1fr 1fr auto',
      widgetAssignments: {
        health: 'main-top',
        agent_status: 'main-left',
        logs: 'main-right',
      },
    },
    {
      id: 'dev-mode',
      name: 'Developer Mode',
      description: 'Layout optimized for development with terminal/editor focus.',
      gridTemplateAreas: [
        '"sidebar dev-main dev-main"',
        '"sidebar dev-bottom dev-right"',
        '"sidebar footer footer"'
      ],
      gridTemplateColumns: 'auto 2fr 1fr',
      gridTemplateRows: '2fr 1fr auto',
      widgetAssignments: {
        logs: 'dev-main', // Terminal/Logs
        task_queue: 'dev-bottom', // For active tasks related to dev
        files: 'dev-right', // Code Editor / File Explorer
      },
    },
    {
      id: 'ops-mode',
      name: 'Operations Mode',
      description: 'Layout focused on system health and metrics.',
      gridTemplateAreas: [
        '"sidebar ops-main ops-main"',
        '"sidebar ops-metrics ops-alerts"',
        '"sidebar footer footer"'
      ],
      gridTemplateColumns: 'auto 2fr 1fr',
      gridTemplateRows: '2fr 1fr auto',
      widgetAssignments: {
        health: 'ops-main', // System Health
        agent_status: 'ops-metrics', // Individual agent health/metrics
        process_control: 'ops-alerts', // Process intervention/alerts
      },
    },
    {
      id: 'focused-mode',
      name: 'Focused Mode',
      description: 'Highlights a single widget for detailed view.',
      gridTemplateAreas: [
        '"sidebar focused-main focused-main"',
        '"sidebar focused-main focused-main"',
        '"sidebar footer footer"'
      ],
      gridTemplateColumns: 'auto 1fr 1fr',
      gridTemplateRows: '1fr 1fr auto',
      widgetAssignments: {
        'health': 'focused-main',
      },
    },
  ],
};

interface LayoutContextType {
  currentLayout: LayoutMode;
  setLayoutMode: (modeId: LayoutModeId) => void;
  layouts: DashboardLayoutConfig;
}

const LayoutContext = createContext<LayoutContextType | undefined>(undefined);

export function LayoutProvider({ children }: { children: ReactNode }) {
  const [activeLayoutId, setActiveLayoutId] = useState<LayoutModeId>(defaultLayoutConfig.defaultMode);

  const currentLayout = useMemo(() => 
    defaultLayoutConfig.modes.find(mode => mode.id === activeLayoutId) || defaultLayoutConfig.modes[0],
    [activeLayoutId]
  );

  const setLayoutMode = useCallback((modeId: LayoutModeId) => {
    if (defaultLayoutConfig.modes.some(mode => mode.id === modeId)) {
      setActiveLayoutId(modeId);
    } else {
      console.warn(`Attempted to set unknown layout mode: ${modeId}`);
    }
  }, []);

  const value = useMemo(() => ({
    currentLayout,
    setLayoutMode,
    layouts: defaultLayoutConfig
  }), [currentLayout, setLayoutMode]);

  return (
    <LayoutContext.Provider value={value}>
      {children}
    </LayoutContext.Provider>
  );
}

export function useLayout() {
  const context = useContext(LayoutContext);
  if (context === undefined) {
    throw new Error('useLayout must be used within a LayoutProvider');
  }
  return context;
}

